#!/usr/bin/env node
// SPDX-License-Identifier: BSD-3-Clause
// gate: assemble the Modbus RTU framer macro generated by
// modbus_rtu_framer.syscfg.js with the real clpru toolchain, verbatim from
// getMacro("") output, and check the generated CRC-16 table against the
// bitwise Modbus reference (poly 0xA001 reflected, init 0xFFFF).
'use strict';
const fs = require('fs'), path = require('path'), vm = require('vm'), child = require('child_process');

function makeStub() { const fn = function () { return makeStub(); }; return new Proxy(fn, { get(_t, p) { if (p === 'toString' || p === Symbol.toPrimitive || p === 'valueOf') return () => ''; return makeStub(); }, apply() { return makeStub(); } }); }
function loadBlock(n, d) {
    const f = path.join(__dirname, '..', '.metadata/sysconfig/.meta/pru_blocks', d, n + '.syscfg.js');
    const s = fs.readFileSync(f, 'utf8');
    const sb = { system: makeStub(), exports: {}, module: { exports: {} }, require: () => makeStub(), console: { log() { }, error() { }, warn() { } } };
    sb.global = sb; vm.createContext(sb); vm.runInContext(s, sb, { filename: f, timeout: 5000 });
    return (sb.exports && Object.keys(sb.exports).length) ? sb.exports : sb.module.exports;
}

const block = loadBlock('modbus_rtu_framer', 'application_specific');
const opCode = 'm_modbus_rtu_rx_frame_pru1_ch2_8x';
const macroDef = block.getMacro('', opCode);
if (!macroDef.includes('.macro') || !macroDef.includes('.endm')) { console.error('FAIL: getMacro("") did not return a macro definition'); process.exit(1); }
// The rejected first attempt put a numeric literal in the .macro parameter
// list (clpru [E0004]). Guard against that class of error explicitly.
const declLine = macroDef.split('\n').find(l => l.includes('.macro'));
if (/\b\d+\s*$/.test(declLine.replace('.macro', '').trim().split(',').pop())) {
    console.error('FAIL: numeric literal in .macro parameter list: ' + declLine); process.exit(1);
}

// Build the assembly: macro definition verbatim + a call with real call-site
// arguments (values are legal at the call site) + buffer and LUT data.
const fakeInst = {
    $name: 'MODBUS_RTU_0', slaveAddress: 17, baudRate: 115200, pruClockMhz: 200,
    clockSource: 0, oversampleSize: 7, channel: 2, pruSelect: 1,
    bufferSymbol: 'modbus_rtu_frame_buf'
};
const callArgs = block.config.find(c => c.name === 'constant1').getValue(fakeInst);
console.log('call-site args (constant1): ' + callArgs);
const lut = block.getLookUptable(fakeInst);

const asm = [
    '    .asg R28, TEMP_REG1',
    '    .asg R29, TEMP_REG2',
    macroDef,
    '    .sect   ".text"',
    '    .global main',
    'main:',
    '    ' + opCode + ' R4, ' + callArgs,
    '    halt',
    '    .sect   ".initdmem"',
    'MODBUS_RTU_0 .ushort ' + lut,
    'modbus_rtu_frame_buf .usect ".udmem", 256, 4',
    ''
].join('\n');

const tmpDir = path.join(__dirname, '..', 'build_out', 'modbus_build_test');
fs.mkdirSync(tmpDir, { recursive: true });
const asmPath = path.join(tmpDir, 'modbus_rtu_framer_test.asm');
fs.writeFileSync(asmPath, asm);

// CRC-16/MODBUS reference checks: table (generated above, parsed back) vs
// bitwise reference; known check value CRC-16/MODBUS("123456789") = 0x4B37.
const table = lut.split(',').map(v => parseInt(v.trim(), 16));
if (table.length !== 256) { console.error('FAIL: LUT must have 256 entries, got ' + table.length); process.exit(1); }
function crcRef(bytes) { let c = 0xFFFF; for (const b of bytes) { c ^= b; for (let i = 0; i < 8; i++) c = (c & 1) ? (c >> 1) ^ 0xA001 : c >> 1; } return c & 0xFFFF; }
function crcTable(bytes) { let c = 0xFFFF; for (const b of bytes) c = ((c >> 8) & 0xFF) ^ table[(c ^ b) & 0xFF]; return c & 0xFFFF; }
const vec = Array.from('123456789').map(c => c.charCodeAt(0));
if (crcRef(vec) !== 0x4B37) { console.error('FAIL: reference self-check (expected 0x4B37)'); process.exit(1); }
if (crcTable(vec) !== crcRef(vec)) { console.error('FAIL: generated table disagrees with bitwise reference'); process.exit(1); }
const frame = [0x01, 0x03, 0x00, 0x00, 0x00, 0x0A];
if (crcTable(frame) !== crcRef(frame)) { console.error('FAIL: table vs reference on Modbus frame'); process.exit(1); }
console.log('CRC check: table == bitwise reference; CRC-16/MODBUS("123456789") = 0x' + crcTable(vec).toString(16).toUpperCase());

// clpru gate — the toolchain that rejected the previous attempt.
const clpru = process.env.CLPRU || (fs.existsSync('/opt/ti-cgt-pru/bin/clpru') ?
    '/opt/ti-cgt-pru/bin/clpru' : 'C:/ti/ti-cgt-pru_2.3.3/bin/clpru.exe');
try {
    child.execSync('"' + clpru + '" --silicon_version=4 -c -o "' +
        path.join(tmpDir, 'modbus_rtu_framer_test.obj') + '" "' + asmPath + '"', { stdio: 'inherit' });
    console.log('Modbus RTU framer clpru build OK: ' + asmPath);
} catch (e) {
    console.error('Modbus RTU framer clpru build FAILED');
    process.exit(1);
}
